def max_balanced_circle(n, heights):
    from collections import defaultdict

    height_count = defaultdict(int)
    for height in heights:
        height_count[height] += 1

    sorted_heights = sorted(height_count.keys())

    max_circle = []
    current_circle = []

    for height in sorted_heights:
        while height_count[height] > 0:
            if len(current_circle) == 0 or abs(current_circle[-1] - height) <= 1:
                current_circle.append(height)
                height_count[height] -= 1
            else:
                if len(current_circle) > len(max_circle):
                    max_circle = current_circle[:]
                current_circle = [height]
                height_count[height] -= 1

    if len(current_circle) > len(max_circle):
        max_circle = current_circle

    # Check if the circle can be extended to form a full circle
    if len(max_circle) > 1 and abs(max_circle[-1] - max_circle[0]) <= 1:
        return max_circle
    else:
        for height in sorted_heights:
            if height_count[height] > 0:
                if abs(max_circle[-1] - height) <= 1:
                    max_circle.append(height)
                    height_count[height] -= 1
                    return max_circle

    return max_circle

