def solve():
    n = int(input())
    heights = list(map(int, input().split()))

    count = [0] * (max(heights) + 2)
    for h in heights:
        count[h] += 1

    total = 0
    current_height = 0
    result = []

    while total < n:
        if count[current_height] > 0 or count[current_height + 1] > 0:
            if count[current_height] >= count[current_height + 1]:
                result.extend([current_height] * count[current_height])
                total += count[current_height]
                count[current_height + 1] = max(0, count[current_height + 1] - count[current_height])
            else:
                result.extend([current_height + 1] * count[current_height + 1])
                total += count[current_height + 1]
                count[current_height] = max(0, count[current_height] - count[current_height + 1])
        else:
            current_height += 1

    print(len(result))
    print(*result)

